import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long gap = nextLong();
        long[] counts = new long[26];
        for (int i = 0; i < s.length(); i++) counts[s.charAt(i) - 'a']++;
        long f = 0, c = 0;
        for (long v : counts) f = Math.max(f, v);
        for (long v : counts) if (v == f) c++;
        // f - 1 full rounds of length gap + 1, then the c most frequent types once more.
        System.out.println(Math.max(s.length(), (f - 1) * (gap + 1) + c));
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	gap := nextInt()
	var counts [26]int
	for _, ch := range s {
		counts[ch-'a']++
	}
	f := slices.Max(counts[:])
	c := 0
	for _, v := range counts {
		if v == f {
			c++
		}
	}
	// f - 1 full rounds of length gap + 1, then the c most frequent types once more.
	os.Stdout.WriteString(strconv.Itoa(max(len(s), (f-1)*(gap+1)+c)) + "\n")
}
